// Parse response and prepare automations
const items = $input.all();
let automations = [];

// Extract automations array
if (items && items.length > 0) {
  const firstItem = items[0].json;
  if (Array.isArray(firstItem)) {
    automations = firstItem;
  } else if (firstItem.data && Array.isArray(firstItem.data)) {
    automations = firstItem.data;
  }
}

console.log(`Found ${automations.length} pending automations`);

// Map practice IDs to Gmail credential IDs
const practiceCredentialMap = {
  'ffed1160-00ec-4c4f-8810-913a24348d90': 'uA0l39VD4cMHN9cC', // NewCharm
  'onehealth_practice_id': 'HrTrOqI74H5m5dyg', // OneHealth - replace with actual practice ID
  // Add more practice mappings here as needed
};

// Group by practice and enrich with credential info
const practiceGroups = {};

automations.forEach(automation => {
  const practiceId = automation.practice_id;

  if (!practiceGroups[practiceId]) {
    practiceGroups[practiceId] = {
      practice_id: practiceId,
      practice_name: automation.practice_name || 'Unknown Practice',
      gmail_credential_id: practiceCredentialMap[practiceId] || null,
      sms_automations: [],
      email_automations: []
    };
  }

  // Split by type
  if (automation.type === 'SMS') {
    practiceGroups[practiceId].sms_automations.push(automation);
  } else if (automation.type === 'EMAIL') {
    practiceGroups[practiceId].email_automations.push(automation);
  }
});

// Convert to array and prepare for processing
const processableGroups = Object.values(practiceGroups).map(group => ({
  json: group
}));

console.log(`Processing ${processableGroups.length} practice groups`);

return processableGroups;

// Process SMS and Email in parallel for this practice
const practiceData = $json;
const outputs = [];

console.log(`Processing ${practiceData.practice_name}:`, {
  sms_count: practiceData.sms_automations.length,
  email_count: practiceData.email_automations.length,
  has_gmail_credentials: !!practiceData.gmail_credential_id
});

// Always output SMS branch (might be empty)
outputs.push({
  json: {
    practice_id: practiceData.practice_id,
    practice_name: practiceData.practice_name,
    type: 'SMS',
    automations: practiceData.sms_automations,
    has_automations: practiceData.sms_automations.length > 0
  }
});

// Always output Email branch (might be empty)
outputs.push({
  json: {
    practice_id: practiceData.practice_id,
    practice_name: practiceData.practice_name,
    type: 'EMAIL',
    gmail_credential_id: practiceData.gmail_credential_id,
    automations: practiceData.email_automations,
    has_automations: practiceData.email_automations.length > 0
  }
});

return outputs;

// Process emails one by one
const emailAutomations = $json.automations || [];
const gmailCredentialId = $json.gmail_credential_id;
const practiceId = $json.practice_id;
const practiceName = $json.practice_name;

return emailAutomations.map(automation => ({
  json: {
    to: automation.recipient_email,
    subject: automation.email_subject,
    body: automation.email_content,
    automation_id: automation.id,
    practice_id: practiceId,
    practice_name: practiceName,
    gmail_credential_id: gmailCredentialId,
    reply_to: automation.practice_email || `noreply@${practiceName.toLowerCase().replace(/\s+/g, '')}.com`
  }
}));

// Dynamic Gmail sending with credential switching
const emailData = $json;

// Map credential IDs to actual credential names in n8n
const credentialMap = {
  'uA0l39VD4cMHN9cC': 'NewCharm Gmail',
  'HrTrOqI74H5m5dyg': 'OneHealth Gmail'
  // Add more mappings as practices are added
};

const credentialName = credentialMap[emailData.gmail_credential_id];

if (!credentialName) {
  console.error(`No Gmail credential mapping found for ID: ${emailData.gmail_credential_id}`);
  return {
    json: {
      success: false,
      automation_id: emailData.automation_id,
      error: 'Gmail credentials not configured for this practice'
    }
  };
}

// Create dynamic Gmail node configuration
const gmailConfig = {
  operation: 'send',
  to: emailData.to,
  subject: emailData.subject,
  message: emailData.body,
  options: {
    replyTo: emailData.reply_to
  },
  credentials: {
    gmailOAuth2: {
      id: emailData.gmail_credential_id,
      name: credentialName
    }
  }
};

// Note: In actual implementation, this would dynamically select the credential
// For now, return the email data for the Gmail node
return {
  json: {
    ...emailData,
    credential_name: credentialName,
    gmail_config: gmailConfig
  }
};

// Collect all results
const results = $input.all();
const updates = [];

results.forEach(result => {
  if (result.json.automation_id) {
    // Single email result
    updates.push({
      id: result.json.automation_id,
      status: result.json.success === false ? 'failed' : 'completed',
      processed_at: new Date().toISOString(),
      error_message: result.json.error || null
    });
  } else if (result.json.automations) {
    // SMS batch result
    const status = result.json.success ? 'completed' : 'failed';
    result.json.automations.forEach(automation => {
      updates.push({
        id: automation.id,
        status: status,
        processed_at: new Date().toISOString(),
        error_message: result.json.error || null
      });
    });
  }
});

console.log(`Collected ${updates.length} results to update`);

return updates.map(update => ({ json: update }));

// Log no credentials error
const practiceData = $json;

console.error(`Practice ${practiceData.practice_name} has no Gmail credentials configured`);

// Mark all email automations as failed
const failedUpdates = practiceData.automations.map(automation => ({
  json: {
    id: automation.id,
    status: 'failed',
    processed_at: new Date().toISOString(),
    error_message: 'No Gmail credentials configured for this practice'
  }
}));

return failedUpdates;
